create table if not exists opening_balance_runs(id bigint generated always as identity primary key,subsidiary_id bigint not null references subsidiaries,opening_date date not null,load_type text not null check(load_type in('FISCAL_YEAR','MID_YEAR')),transition_account_id bigint not null references chart_accounts,status text not null default'DRAFT'check(status in('DRAFT','VALIDATED','POSTED','REVERSED')),journal_id bigint references journal,created_by bigint references users,created_at timestamptz default now(),posted_at timestamptz,reversed_at timestamptz,unique(subsidiary_id)include(status));
create table if not exists opening_balance_lines(id bigint generated always as identity primary key,run_id bigint not null references opening_balance_runs on delete cascade,source_type text not null check(source_type in('GL','AR','AP')),row_number int not null,account_id bigint not null references chart_accounts,entity_id bigint,document_number text,issue_date date,due_date date,currency_id bigint not null references currencies,historical_rate numeric(24,10)not null,foreign_amount numeric(24,6)not null,local_debit numeric(24,6)not null default 0,local_credit numeric(24,6)not null default 0,cost_center_id bigint references cost_centers,location_id bigint references locations,project_code text,note text,raw_data jsonb not null default'{}',unique(run_id,source_type,row_number),check((local_debit>0)<>(local_credit>0)));
alter table journal add column if not exists is_opening_balance boolean not null default false;
alter table journal_line add column if not exists historical_exchange_rate numeric(24,10),add column if not exists original_currency_id bigint references currencies,add column if not exists opening_balance_line_id bigint references opening_balance_lines;
alter table opening_balance_runs enable row level security;alter table opening_balance_lines enable row level security;
create policy obr_read on opening_balance_runs for select to authenticated using(subsidiary_id=active_subsidiary_id());create policy obl_read on opening_balance_lines for select to authenticated using(exists(select 1 from opening_balance_runs r where r.id=run_id and r.subsidiary_id=active_subsidiary_id()));
create or replace function opening_balance_options()returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('subsidiary',jsonb_build_object('id',s.subsidiary_id,'name',s.name,'currencyId',s.currency_id,'currency',cu.currency_code),'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',a.account_id,'number',a.account_number,'name',a.account_name,'category',a.category)order by a.account_number)from chart_accounts a join account_subsidiaries x using(account_id)where x.subsidiary_id=s.subsidiary_id and x.is_active and a.accepts_entries and not a.is_inactive),'[]'),'currencies',(select jsonb_agg(jsonb_build_object('id',currency_id,'code',currency_code))from currencies),'costCenters',coalesce((select jsonb_agg(jsonb_build_object('id',cost_center_id,'code',code,'name',name))from cost_centers where subsidiary_id=s.subsidiary_id),'[]'),'locations',coalesce((select jsonb_agg(jsonb_build_object('id',location_id,'name',name))from locations where subsidiary_id=s.subsidiary_id),'[]'),'customers',(select coalesce(jsonb_agg(jsonb_build_object('id',customer_id,'taxId',tax_id,'name',company_name)),'[]')from customers c where c.primary_subsidiary_id=s.subsidiary_id or exists(select 1 from entity_subsidiaries e where e.customer_id=c.customer_id and e.subsidiary_id=s.subsidiary_id)),'suppliers',(select coalesce(jsonb_agg(jsonb_build_object('id',supplier_id,'taxId',tax_id,'name',company_name)),'[]')from suppliers p where p.primary_subsidiary_id=s.subsidiary_id or exists(select 1 from entity_subsidiaries e where e.supplier_id=p.supplier_id and e.subsidiary_id=s.subsidiary_id)),'run',(select to_jsonb(r)from opening_balance_runs r where r.subsidiary_id=s.subsidiary_id and r.status<>'REVERSED'limit 1))from subsidiaries s join currencies cu using(currency_id)where s.subsidiary_id=active_subsidiary_id()$$;
create or replace function opening_balance_rate(p_currency bigint,p_date date)returns numeric language plpgsql stable security definer set search_path=public as $$declare base bigint:= (select currency_id from subsidiaries where subsidiary_id=active_subsidiary_id());r numeric;begin if p_currency=base then return 1;end if;select spot_rate into r from exchange_rates where from_currency_id=p_currency and to_currency_id=base and effective_date<=p_date order by effective_date desc limit 1;if r is null then raise exception'No existe tipo de cambio para la moneda seleccionada a la fecha de apertura.';end if;return r;end$$;
create or replace function opening_balance_stage(p jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare rid bigint;row jsonb;n int:=0;rate numeric;acc bigint;cur bigint;ent bigint;debit numeric;credit numeric;begin if exists(select 1 from opening_balance_runs where subsidiary_id=active_subsidiary_id()and status='POSTED')then raise exception'Ya existe una apertura contabilizada para esta subsidiaria.';end if;delete from opening_balance_runs where subsidiary_id=active_subsidiary_id()and status in('DRAFT','VALIDATED');insert into opening_balance_runs(subsidiary_id,opening_date,load_type,transition_account_id,created_by)values(active_subsidiary_id(),(p->>'openingDate')::date,p->>'loadType',(p->>'transitionAccountId')::bigint,app_user_id())returning id into rid;for row in select value from jsonb_array_elements(p->'rows')loop n:=n+1;select account_id into acc from chart_accounts where account_number=row->>'account';select currency_id into cur from currencies where currency_code=upper(row->>'currency');if acc is null or cur is null then raise exception'Fila %: cuenta o moneda inválida.',n;end if;rate:=opening_balance_rate(cur,(p->>'openingDate')::date);debit:=coalesce(nullif(row->>'debit','')::numeric,0)*rate;credit:=coalesce(nullif(row->>'credit','')::numeric,0)*rate;if(debit>0)=(credit>0)then raise exception'Fila %: indique débito o crédito.',n;end if;insert into opening_balance_lines(run_id,source_type,row_number,account_id,document_number,issue_date,due_date,currency_id,historical_rate,foreign_amount,local_debit,local_credit,project_code,note,raw_data)values(rid,row->>'sourceType',n,acc,nullif(row->>'documentNumber',''),nullif(row->>'issueDate','')::date,nullif(row->>'dueDate','')::date,cur,rate,greatest(coalesce(nullif(row->>'debit','')::numeric,0),coalesce(nullif(row->>'credit','')::numeric,0)),debit,credit,row->>'project',row->>'note',row);end loop;return(select jsonb_build_object('runId',rid,'rows',count(*),'debit',sum(local_debit),'credit',sum(local_credit),'difference',sum(local_debit)-sum(local_credit))from opening_balance_lines where run_id=rid);end$$;
grant execute on function opening_balance_options(),opening_balance_rate(bigint,date),opening_balance_stage(jsonb)to authenticated;notify pgrst,'reload schema';
